def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def count_up_to(n: int) -> int:
        if n < 0:
            return 0
        suffix_val = int(s)
        suffix_len = len(s)
        power10 = 10 ** suffix_len

        for c in s:
            if int(c) > limit:
                return 0

        max_p = (n - suffix_val) // power10
        if max_p < 0:
            return 0

        s_max_p = str(max_p)
        L = len(s_max_p)
        memo = {}

        def dp(idx: int, tight: bool, leading_zero: bool) -> int:
            if idx == L:
                return 1
            state = (idx, tight, leading_zero)
            if state in memo:
                return memo[state]

            limit_digit = int(s_max_p[idx]) if tight else 9
            count = 0

            for d in range(0, limit_digit + 1):
                if not leading_zero:
                    if d > limit:
                        continue
                else:
                    if d > 0 and d > limit:
                        continue

                new_tight = tight and (d == limit_digit)
                new_leading_zero = leading_zero and (d == 0)
                count += dp(idx + 1, new_tight, new_leading_zero)

            memo[state] = count
            return count

        return dp(0, True, True)

    return count_up_to(finish) - count_up_to(start - 1)

