def min_absolute_difference(nums: List[int], k: int) -> int:
    min_diff = float('inf')
    distinct_ors = []
    for x in nums:
        new_ors = {x}
        for val in distinct_ors:
            new_ors.add(val | x)
        for val in new_ors:
            diff = abs(k - val)
            if diff < min_diff:
                min_diff = diff
        distinct_ors = list(new_ors)
    return min_diff

