def card_game_winner(n: int, cards: List[Tuple[int, int]]) -> str:
    """ Two players are playing a card game. Each card has a front number and a back number.
    Players take turns removing pairs of cards where either the front numbers match or the back numbers match.
    The player who cannot make a move loses.

    Takahashi goes first. Both players play optimally.

    Args:
        n: Number of cards (1 <= n <= 18)
        cards: List of tuples where cards[i] = (A_i, B_i) represents the front and back numbers of card i

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins
    """
    # Convert to tuples for immutability if needed, but input is already tuples
    @lru_cache(maxsize=None)
    def can_win(mask: int) -> bool:
        # Try all possible moves: pick two remaining cards i, j such that
        # cards[i].front == cards[j].front or cards[i].back == cards[j].back
        # If any move leads to a state where the opponent cannot win, current player wins.
        remaining = []
        for i in range(n):
            if mask & (1 << i):
                remaining.append(i)

        if not remaining:
            return False  # No moves, current player loses

        for i in range(len(remaining)):
            for j in range(i + 1, len(remaining)):
                idx1, idx2 = remaining[i], remaining[j]
                c1, c2 = cards[idx1], cards[idx2]
                if c1[0] == c2[0] or c1[1] == c2[1]:
                    new_mask = mask ^ (1 << idx1) ^ (1 << idx2)
                    if not can_win(new_mask):
                        return True
        return False

    if not can_win((1 << n) - 1):
        return "Aoki"
    else:
        return "Takahashi"

