def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """ Given an undirected tree with n vertices (numbered 1 to n) and edges connecting them,
    find the maximum number of vertices in a subgraph that forms an alkane.

    An alkane is defined as:
    - An undirected tree
    - Every vertex has degree 1 or 4
    - There is at least one vertex of degree 4

    If no such subgraph exists, return -1.
    """
    if n < 1:
        return -1

    if len(edges) == 0:
        return -1

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    original_degree = [len(adj[i]) for i in range(n + 1)]
    current_deg = list(original_degree)
    removed = [False] * (n + 1)

    queue = deque()
    for i in range(1, n + 1):
        if current_deg[i] != 1 and current_deg[i] != 4:
            queue.append(i)

    while queue:
        u = queue.popleft()
        if removed[u]:
            continue
        if current_deg[u] == 1 or current_deg[u] == 4:
            continue
        removed[u] = True

        for v in adj[u]:
            if not removed[v]:
                current_deg[v] -= 1
                if current_deg[v] != 1 and current_deg[v] != 4:
                    queue.append(v)

    active_nodes = [i for i in range(1, n + 1) if not removed[i]]
    if not active_nodes:
        return -1

    visited = [False] * (n + 1)
    best_size = -1

    for start in active_nodes:
        if visited[start]:
            continue

        stack = [start]
        visited[start] = True
        component_nodes = [start]

        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not removed[v] and not visited[v]:
                    visited[v] = True
                    stack.append(v)
                    component_nodes.append(v)

        has_degree_4 = False
        for u in component_nodes:
            if current_deg[u] == 4:
                has_degree_4 = True
                break

        if has_degree_4:
            if len(component_nodes) > best_size:
                best_size = len(component_nodes)

    return best_size

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    MOD = 998244353

    def get_divisors(num):
        divs = []
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divs.append(i)
                if i * i != num:
                    divs.append(num // i)
        return divs

    total_score = 0
    divs = get_divisors(a[0])

    for s0 in divs:
        seq = [s0]
        valid = True
        curr_gcd = s0

        for i in range(n - 1):
            prev = seq[-1]
            target = a[i]
            if target % prev != 0:
                valid = False
                break
            next_val = target // prev
            if gcd(prev, next_val) != 1:
                valid = False
                break
            seq.append(next_val)
            curr_gcd = gcd(curr_gcd, next_val)

        if valid and curr_gcd == 1:
            prod = 1
            for x in seq:
                prod = (prod * x) % MOD
            total_score = (total_score + prod) % MOD

    return total_score

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

