from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """ Find a non-empty subsequence of nums that has an alternating sum equal to k
    and maximizes the product of all its numbers without exceeding limit.

    The alternating sum is calculated based on the indices within the subsequence itself:
    sum(sub[0]) - sum(sub[1]) + sum(sub[2]) - ...
    """
    n = len(nums)
    if n == 0:
        return -1

    # dp_even[s] = max product of a subsequence (even length) with alternating sum = s
    # dp_odd[s] = max product of a subsequence (odd length) with alternating sum = s
    even_dp = {}
    odd_dp = {}

    for x in nums:
        next_even_dp = dict(even_dp)
        next_odd_dp = dict(odd_dp)

        # 1. Start a new sequence with x
        # Length 1 (Odd), Sum = x, Product = x
        if x > next_odd_dp.get(x, -1):
            next_odd_dp[x] = x

        # 2. Extend existing even_dp sequences
        # Current length even -> append x makes it odd index in subseq -> subtract x
        # New sum = s - x, New product = p * x
        for s, p in even_dp.items():
            if p == 0 and x == 0:
                continue
            new_p = p * x
            if new_p > next_odd_dp.get(s - x, -1):
                next_odd_dp[s - x] = new_p

        # 3. Extend existing odd_dp sequences
        # Current length odd -> append x makes it even index in subseq -> add x
        # New sum = s + x, New product = p * x
        for s, p in odd_dp.items():
            if p == 0 and x == 0:
                continue
            new_p = p * x
            if new_p > next_even_dp.get(s + x, -1):
                next_even_dp[s + x] = new_p

        even_dp = next_even_dp
        odd_dp = next_odd_dp

    candidates = []
    if k in even_dp:
        prod = even_dp[k]
        if prod <= limit:
            candidates.append(prod)
    if k in odd_dp:
        prod = odd_dp[k]
        if prod <= limit:
            candidates.append(prod)

    if not candidates:
        return -1

    return max(candidates)

