def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    total_cost = 0

    for d in sections:
        if d == 0:
            continue
        if L1 == 0 and L2 == 0:
            return -1

        best_cost = float('inf')

        # Iterate over number of type 1 sensors
        # We can optimize the range, but K1 is at most 1000, so this loop is fine.
        for k1 in range(K1 + 1):
            remaining = d - k1 * L1
            needed = 0

            if remaining > 0:
                if L2 > 0:
                    needed = math.ceil(remaining / L2)
                else:
                    needed = float('inf')
            else:
                needed = 0

            k2 = needed
            if k2 > K2 or k2 == float('inf'):
                continue

            cost = k1 * C1 + k2 * C2
            if cost < best_cost:
                best_cost = cost

        if best_cost == float('inf'):
            return -1

        total_cost += best_cost

    return total_cost

