    def get_max_run(arr, strictly_inc):
        if not arr:
            return 0
        max_len = 1
        current_len = 1
        for i in range(1, len(arr)):
            if strictly_inc:
                if arr[i] > arr[i-1]:
                    current_len += 1
                else:
                    max_len = max(max_len, current_len)
                    current_len = 1
            else:
                if arr[i] < arr[i-1]:
                    current_len += 1
                else:
                    max_len = max(max_len, current_len)
                    current_len = 1
        return max(max_len, current_len)

    max_inc = get_max_run(seen, strictly_inc=True)
    max_dec = get_max_run(seen, strictly_inc=False)
    return max(max_inc, max_dec)

def solve(view):
    n = view.total_length
    account = [0] * n
    for i in range(n):
        if i == 0:
            account[i] = view.peek(i)
        else:
            account[i] = 5  # Based on the guarantee

    total_sum = sum(account)
    k = total_sum // n
    r = [x - k for x in account]

    max_squares = k * n

    for start in range(n):
        current_r = list(r)
        t = 0
        while True:
            color_idx = (start + t) % n
            if current_r[color_idx] == 0:
                break
            current_r[color_idx] -= 1
            t += 1
        max_squares = max(max_squares, k * n + t)

    return max_squares

def solve(view):
