    words = []
    for i in range(n):
        words.append(view.peek(i))

    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            prefix = words[i]
            suffix_target = words[j]
            if len(prefix) > len(suffix_target):
                continue
            is_prefix = suffix_target.startswith(prefix)
            is_suffix = suffix_target.endswith(prefix)
            if is_prefix and is_suffix:
                count += 1
    return count

